import{_ as s,o as a,c as i,a5 as r}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"x86 汇编基础","description":"本专题主线是 x64，但很多老程序、老壳、老工具仍是 32 位 x86。理解 x86 与 x64 的差异，才能在遇到 32 位目标时从容切换。这一章讲 x86 的核心：寄存器、寻址、调用约定，重点放在它与 x64 的不同。","frontmatter":{"type":"explanation","level":"basic"},"headers":[],"relativePath":"reverse-engineering/02-assembly/chapter-01-x86-assembly.md","filePath":"reverse-engineering/02-assembly/chapter-01-x86-assembly.md"}'),l={name:"reverse-engineering/02-assembly/chapter-01-x86-assembly.md"};function n(t,e,d,p,c,h){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="x86-汇编基础" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">x86 汇编基础 <a class="header-anchor" href="#x86-汇编基础" aria-label="Permalink to &quot;x86 汇编基础&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">本专题主线是 x64，但很多老程序、老壳、老工具仍是 32 位 x86。理解 x86 与 x64 的差异，才能在遇到 32 位目标时从容切换。这一章讲 x86 的核心：寄存器、寻址、调用约定，重点放在它与 x64 的不同。</p><h2 id="_1-寄存器-32-位-更少" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">1. 寄存器：32 位，更少 <a class="header-anchor" href="#_1-寄存器-32-位-更少" aria-label="Permalink to &quot;1. 寄存器：32 位，更少&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">x86 有 8 个通用寄存器，每个 32 位：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>EAX  EBX  ECX  EDX  ESI  EDI  EBP  ESP</span></span></code></pre></div><p data-src-line="14" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">和 x64 的关系：x64 的这些寄存器是 64 位扩展版（<code>RAX</code> 是 <code>EAX</code> 的 64 位版）。x86 只有 8 个寄存器，比 x64 的 16 个少，因此编译器更依赖栈来存临时值。</p><p data-src-line="16" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">特殊寄存器：</p><ul data-src-line="18" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><li data-src-line="18" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><strong>EIP</strong>：指令指针（x64 的 RIP 的 32 位版）。</li><li data-src-line="19" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><strong>EFLAGS</strong>：标志寄存器。</li><li data-src-line="20" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><strong>ESP</strong>：栈指针（几乎只用于栈顶）。</li></ul><h2 id="_2-调用约定-栈传参-vs-寄存器传参" tabindex="-1" data-src-line="22" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">2. 调用约定：栈传参 vs 寄存器传参 <a class="header-anchor" href="#_2-调用约定-栈传参-vs-寄存器传参" aria-label="Permalink to &quot;2. 调用约定：栈传参 vs 寄存器传参&quot;">​</a></h2><p data-src-line="24" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">x86 和 x64 最大的区别在<strong>调用约定</strong>。x86 有多个约定，但都靠<strong>栈</strong>传参；x64 统一用寄存器传前几个参数。</p><p data-src-line="26" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><strong>cdecl</strong>（C 默认约定）：</p><ul data-src-line="28" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><li data-src-line="28" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">参数从右到左压栈。</li><li data-src-line="29" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">调用者负责清理栈（<code>add esp, N</code>）。</li><li data-src-line="30" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">支持变参（如 <code>printf</code>）。</li></ul><p data-src-line="32" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><strong>stdcall</strong>（Win32 API 约定）：</p><ul data-src-line="34" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><li data-src-line="34" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">参数从右到左压栈。</li><li data-src-line="35" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">被调函数负责清理栈（<code>ret N</code>）。</li><li data-src-line="36" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">Win32 API（<code>kernel32</code> 等 32 位版）都用这个。</li></ul><p data-src-line="38" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><strong>fastcall</strong>：</p><ul data-src-line="40" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><li data-src-line="40" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">前两个参数用 <code>ECX</code>、<code>EDX</code>，其余压栈。</li></ul><p data-src-line="42" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">对比记忆：<strong>x86 参数在栈上，x64 参数在寄存器里。</strong> 这是两代架构最影响读反汇编的差异。</p><p data-src-line="44" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">看一个 cdecl 调用的例子，调用 <code>add(3, 5)</code>：</p><div class="language-asm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">asm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          ; 参数从右到左，先压 5</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          ; 再压 3</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">call</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> add</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        ; 调用</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  esp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     ; 调用者清理 8 字节栈（两个 int）</span></span></code></pre></div><p data-src-line="53" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">而同样的调用在 x64 下是 <code>mov ecx, 3; mov edx, 5; call add</code>，参数直接进寄存器。</p><h2 id="_3-栈帧-push-ebp-的经典模式" tabindex="-1" data-src-line="55" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">3. 栈帧：push ebp 的经典模式 <a class="header-anchor" href="#_3-栈帧-push-ebp-的经典模式" aria-label="Permalink to &quot;3. 栈帧：push ebp 的经典模式&quot;">​</a></h2><p data-src-line="57" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">x86 的栈帧建立非常典型，几乎每个函数开头都是：</p><div class="language-asm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">asm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">push</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ebp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        ; 保存旧帧指针</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">mov</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  ebp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">esp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   ; 建立新帧指针</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  esp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40h</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   ; 为局部变量留空间</span></span></code></pre></div><p data-src-line="65" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">结尾对应：</p><div class="language-asm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">asm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">mov</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  esp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ebp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   ; 恢复栈顶</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  ebp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        ; 恢复旧帧指针</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ret</span></span></code></pre></div><p data-src-line="73" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><code>EBP</code> 作为帧指针，<code>[ebp - 偏移]</code> 访问局部变量，<code>[ebp + 偏移]</code> 访问参数。这个「push ebp / mov ebp, esp」的模式，是识别 x86 函数边界的标志。</p><p data-src-line="75" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">而在 x64 下，编译器常常<strong>省略帧指针</strong>，直接用 <code>RSP</code> 计算偏移，所以看不到这个模式。这是识别「这是 32 位还是 64 位代码」的一个线索。</p><h2 id="_4-数据宽度与指令" tabindex="-1" data-src-line="77" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">4. 数据宽度与指令 <a class="header-anchor" href="#_4-数据宽度与指令" aria-label="Permalink to &quot;4. 数据宽度与指令&quot;">​</a></h2><p data-src-line="79" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">x86 操作 32 位数据，常用宽度后缀是 <code>byte</code>、<code>word</code>、<code>dword</code>。指令集和 x64 大部分重合，但 x64 扩展了 64 位操作（<code>rax</code>、<code>qword</code>）。</p><p data-src-line="81" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">一个常见现象：x86 反汇编里 <code>mov eax, [esp+4]</code> 这种「用 ESP 直接访问参数」的写法很常见（因为没有多余寄存器），x64 里则更多用 <code>rsp</code> 或帧指针。</p><h2 id="_5-什么时候会遇到-x86" tabindex="-1" data-src-line="83" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">5. 什么时候会遇到 x86 <a class="header-anchor" href="#_5-什么时候会遇到-x86" aria-label="Permalink to &quot;5. 什么时候会遇到 x86&quot;">​</a></h2><p data-src-line="85" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">虽然本专题主线是 x64，但你会在这几种场景遇到 x86：</p><ul data-src-line="87" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><li data-src-line="87" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">分析老的 32 位程序、老壳、老插件。</li><li data-src-line="88" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">32 位 DLL 被 64 位程序通过 WoW64 兼容层加载。</li><li data-src-line="89" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">一些 shellcode 仍是 32 位（体积更小）。</li></ul><p data-src-line="91" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">遇到 x86 目标时，用 x32dbg（而不是 x64dbg）调试，用 32 位视角读反汇编，注意参数在栈上、寄存器更少这两个核心差异。</p><hr><blockquote data-src-line="95" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md"><p data-src-line="95" data-src-file="reverse-engineering/02-assembly/chapter-01-x86-assembly.md">本章建立的是 x86 的图景：8 个 32 位寄存器，参数靠栈传递，经典 <code>push ebp</code> 栈帧。它与 x64 的核心差异是「栈传参 vs 寄存器传参」。下一章进入本专题主线的 <a href="./chapter-02-x64-assembly.html">x64 汇编</a>。</p></blockquote>`,36)])])}const o=s(l,[["render",n]]);export{m as __pageData,o as default};
